export { TableBulkActions as DataTableBulkActions } from "@/components/blocks/data-table/bulk-actions";
export { DataTableColumnHeader } from "@/components/blocks/data-table/column-header";
export {
  DataTableColumnSettings,
  type DataTableColumnSettingsProps,
} from "@/components/blocks/data-table/column-settings";
export {
  DataTableDensity,
  type DataTableDensityProps,
  type DataTableDensityValue,
} from "@/components/blocks/data-table/density";
export { DataTableFacetedFilter } from "@/components/blocks/data-table/faceted-filter";
export type {
  ColumnFilterConfig,
  DataTableColumnDef,
  DataTableProps,
  DataTableRenderContext,
  DataTableState,
  TableFeatures,
  TableLabelOverrides,
  TableLabels,
  TableRowKey,
} from "@/components/blocks/data-table/index";
export {
  DataTable,
  useDataTableUrlState,
} from "@/components/blocks/data-table/index";
export { DataTablePagination } from "@/components/blocks/data-table/pagination";
export {
  DataTableRefresh,
  type DataTableRefreshProps,
} from "@/components/blocks/data-table/refresh";
export {
  DataTableSearch,
  type DataTableSearchProps,
} from "@/components/blocks/data-table/search-bar";

"use client";

import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { RowData } from "@tanstack/react-table";
import { Button } from "@/components/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import { TableCell, TableRow } from "@/components/ui/table";
import { cn } from "cn";
import { GripVertical, Inbox } from "lucide-react";
import type { CSSProperties, ReactNode } from "react";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import { type Cell, type Column, flexRender, type Row } from "@/components/blocks/data-table/types";

const TABLE_ROW_CLASS_NAME = "group/row bg-background";
const TABLE_CELL_STATE_CLASS_NAME = "bg-inherit bg-clip-padding";
const TABLE_ROW_COLOR_TRANSITION =
  "color 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), border-color 150ms cubic-bezier(0.4, 0, 0.2, 1)";

/** Measured left and right offsets for sticky table columns. */
export interface TablePinnedColumnOffsets {
  start: Record<string, number>;
  end: Record<string, number>;
  dragWidth: number;
  headerTop: number[];
}

/** Renders loading, empty, static, and sortable Table rows. */
export function TableBody<TData extends RowData>({
  rows,
  visibleColumns,
  visibleColumnCount,
  dragSort,
  loading,
  loadingRows,
  paddingClass,
  emptyFallbackText,
  onRetry,
  pinnedOffsets,
  labels = defaultTableLabels,
}: Readonly<{
  rows: Row<TData>[];
  visibleColumns: ReturnType<Row<TData>["getVisibleCells"]>[number]["column"][];
  visibleColumnCount: number;
  dragSort: boolean;
  loading: boolean;
  loadingRows: number;
  paddingClass: string;
  emptyFallbackText?: ReactNode;
  onRetry?: () => void;
  pinnedOffsets: TablePinnedColumnOffsets;
  labels?: TableLabels;
}>) {
  const emptyRow = (
    <TableRow data-slot="ui-table-row" className={TABLE_ROW_CLASS_NAME}>
      <TableCell
        colSpan={visibleColumnCount}
        className={cn("h-32", TABLE_CELL_STATE_CLASS_NAME)}
      >
        <Empty>
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <Inbox />
            </EmptyMedia>
            <EmptyTitle>{emptyFallbackText ?? labels.noData}</EmptyTitle>
          </EmptyHeader>
          {onRetry && (
            <EmptyContent>
              <Button variant="outline" size="sm" onClick={onRetry}>
                {labels.retry}
              </Button>
            </EmptyContent>
          )}
        </Empty>
      </TableCell>
    </TableRow>
  );

  if (loading) {
    return Array.from({ length: loadingRows }, (_, index) => (
      <TableRow
        // biome-ignore lint/suspicious/noArrayIndexKey: skeleton rows are fixed placeholders.
        key={`skeleton-row-${index}`}
        className={TABLE_ROW_CLASS_NAME}
      >
        {dragSort && (
          <TableCell
            data-ui-table-drag-column=""
            className={cn(
              "sticky inset-s-0 z-20 w-10 p-2 text-center align-middle",
              TABLE_CELL_STATE_CLASS_NAME,
            )}
          >
            <Skeleton data-slot="ui-table-skeleton" className="size-4" />
          </TableCell>
        )}
        {visibleColumns.map((column) => (
          <TableCell
            key={column.id}
            className={getPinnedColumnClassName(
              column,
              cn(
                "border-b",
                TABLE_CELL_STATE_CLASS_NAME,
                column.columnDef.meta?.className,
              ),
            )}
            style={getPinnedColumnStyle(column, pinnedOffsets)}
            data-ui-table-column-id={column.id}
          >
            <Skeleton data-slot="ui-table-skeleton" className="h-4 w-full" />
          </TableCell>
        ))}
      </TableRow>
    ));
  }

  if (dragSort) {
    return (
      <SortableContext
        items={rows.map((row) => row.id)}
        strategy={verticalListSortingStrategy}
      >
        {rows.map((row) => (
          <SortableRow
            key={row.id}
            row={row}
            paddingClass={paddingClass}
            labels={labels}
          >
            {row.getVisibleCells().map((cell) => (
              <BodyCell
                key={cell.id}
                cell={cell}
                paddingClass={paddingClass}
                pinnedOffsets={pinnedOffsets}
              />
            ))}
          </SortableRow>
        ))}
        {rows.length === 0 && emptyRow}
      </SortableContext>
    );
  }

  if (rows.length === 0) return emptyRow;
  return rows.map((row) => (
    <TableRow
      key={row.id}
      data-state={row.getIsSelected() && "selected"}
      className={TABLE_ROW_CLASS_NAME}
    >
      {row.getVisibleCells().map((cell) => (
        <BodyCell
          key={cell.id}
          cell={cell}
          paddingClass={paddingClass}
          pinnedOffsets={pinnedOffsets}
        />
      ))}
    </TableRow>
  ));
}

function BodyCell<TData extends RowData>({
  cell,
  paddingClass,
  pinnedOffsets,
}: Readonly<{
  cell: Cell<TData, unknown>;
  paddingClass: string;
  pinnedOffsets: TablePinnedColumnOffsets;
}>) {
  const meta = cell.column.columnDef.meta;
  const pinned = cell.column.getIsPinned();
  const align = meta?.align ?? (pinned === "end" ? "end" : pinned || undefined);

  return (
    <TableCell
      className={getPinnedColumnClassName(
        cell.column,
        cn(
          "border-b",
          TABLE_CELL_STATE_CLASS_NAME,
          paddingClass,
          align === "center" && "text-center",
          align === "end" && "text-end",
          align === "start" && "text-start",
          meta?.className,
        ),
      )}
      style={getPinnedColumnStyle(cell.column, pinnedOffsets)}
      data-ui-table-column-id={cell.column.id}
    >
      <div
        data-slot="data-table-cell-content"
        className={cn(
          "flex min-w-0 items-center gap-2",
          align === "center" && "justify-center",
          align === "end" && "justify-end",
        )}
      >
        {flexRender(cell.column.columnDef.cell, cell.getContext())}
      </div>
    </TableCell>
  );
}

function SortableRow<TData extends RowData>({
  row,
  children,
  paddingClass,
  labels,
}: Readonly<{
  row: Row<TData>;
  children: ReactNode;
  paddingClass: string;
  labels: TableLabels;
}>) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: row.id,
  });

  return (
    <TableRow
      ref={setNodeRef}
      data-state={row.getIsSelected() && "selected"}
      className={TABLE_ROW_CLASS_NAME}
      style={{
        transform: CSS.Transform.toString(transform),
        transition: [transition, TABLE_ROW_COLOR_TRANSITION]
          .filter(Boolean)
          .join(", "),
        opacity: isDragging ? 0.5 : 1,
        position: isDragging ? "relative" : undefined,
        zIndex: isDragging ? 10 : undefined,
      }}
    >
      <TableCell
        data-ui-table-drag-column=""
        className={cn(
          "border-b",
          paddingClass,
          TABLE_CELL_STATE_CLASS_NAME,
          "sticky inset-s-0 z-20 w-10 px-2 text-center",
        )}
      >
        <Button
          variant="ghost"
          size="icon-xs"
          {...attributes}
          {...listeners}
          className="cursor-grab touch-none active:cursor-grabbing"
          aria-label={labels.dragReorder}
        >
          <GripVertical />
        </Button>
      </TableCell>
      {children}
    </TableRow>
  );
}

/** Returns sticky-column classes shared by table headers and body cells. */
export function getPinnedColumnClassName<TData extends RowData>(
  column: Column<TData, unknown>,
  className?: string,
) {
  const pinned = column.getIsPinned();

  return cn(
    column.columnDef.meta?.__uiTableFixedSize !== undefined && "truncate",
    pinned && "sticky z-10",
    className,
  );
}

/** Computes sticky-column inline offsets after measured widths are applied. */
export function getPinnedColumnStyle<TData extends RowData>(
  column: Column<TData, unknown>,
  offsets: TablePinnedColumnOffsets,
): CSSProperties {
  const pinned = column.getIsPinned();
  const style: CSSProperties = {};
  const fixedSize = column.columnDef.meta?.__uiTableFixedSize;

  if (typeof fixedSize === "number") {
    style.width = `${fixedSize}px`;
    style.minWidth = `${fixedSize}px`;
    style.maxWidth = `${fixedSize}px`;
  }

  if (pinned === "start") {
    const left =
      offsets.start[column.id] ?? column.getStart("start") + offsets.dragWidth;
    style.insetInlineStart = `${left}px`;
  }
  if (pinned === "end") {
    style.insetInlineEnd = `${offsets.end[column.id] ?? column.getAfter("end")}px`;
  }

  return style;
}

import type { RowData } from "@tanstack/react-table";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { X } from "lucide-react";
import {
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import { TooltipButton } from "@/components/blocks/data-table/tooltip-button";
import type { Table } from "@/components/blocks/data-table/types";

/** Floating keyboard-accessible actions for selected table rows. */
export function TableBulkActions<TData extends RowData>({
  table,
  children,
  disabled = false,
  labels = defaultTableLabels,
}: Readonly<{
  table: Table<TData>;
  children?: ReactNode;
  disabled?: boolean;
  labels?: TableLabels;
}>) {
  const selectedCount = table.getFilteredSelectedRowModel().rows.length;
  const descriptionId = useId();
  const toolbarRef = useRef<HTMLDivElement>(null);
  const [announcement, setAnnouncement] = useState("");

  useEffect(() => {
    if (selectedCount === 0) return;

    queueMicrotask(() =>
      setAnnouncement(labels.bulkAnnouncement(selectedCount)),
    );

    const timer = setTimeout(() => setAnnouncement(""), 3000);
    return () => clearTimeout(timer);
  }, [selectedCount, labels]);

  function handleKeyDown(event: KeyboardEvent) {
    const buttons = toolbarRef.current?.querySelectorAll<HTMLButtonElement>(
      "button:not(:disabled)",
    );
    if (!buttons?.length) return;
    const isRtl =
      toolbarRef.current &&
      getComputedStyle(toolbarRef.current).direction === "rtl";

    const activeElement = document.activeElement;
    const currentIndex =
      activeElement instanceof HTMLButtonElement
        ? Array.from(buttons).indexOf(activeElement)
        : -1;

    switch (event.key) {
      case "ArrowRight": {
        event.preventDefault();
        const offset = isRtl ? -1 : 1;
        buttons[
          (currentIndex + offset + buttons.length) % buttons.length
        ]?.focus();
        break;
      }
      case "ArrowLeft": {
        event.preventDefault();
        const offset = isRtl ? 1 : -1;
        buttons[
          (currentIndex + offset + buttons.length) % buttons.length
        ]?.focus();
        break;
      }
      case "Home": {
        event.preventDefault();
        buttons[0]?.focus();
        break;
      }
      case "End": {
        event.preventDefault();
        buttons[buttons.length - 1]?.focus();
        break;
      }
      case "Escape": {
        const target =
          event.target instanceof HTMLElement ? event.target : null;
        const dropdownSelector =
          '[data-slot="dropdown-menu-trigger"], [data-slot="dropdown-menu-content"]';

        if (
          target?.closest(dropdownSelector) ||
          (activeElement instanceof HTMLElement &&
            activeElement.closest(dropdownSelector))
        ) {
          return;
        }

        event.preventDefault();
        table.resetRowSelection();
        break;
      }
    }
  }

  if (selectedCount === 0) return null;

  return (
    <>
      <div
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
        role="status"
      >
        {announcement}
      </div>

      <div
        ref={toolbarRef}
        inert={disabled}
        aria-busy={disabled}
        role="toolbar"
        aria-label={labels.bulkToolbar(selectedCount)}
        aria-describedby={descriptionId}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
        className="fixed bottom-[calc(1.5rem+env(safe-area-inset-bottom))] left-1/2 z-40 w-max max-w-[calc(100vw-2rem)] -translate-x-1/2 rounded-3xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        <div className="flex items-center gap-2 overflow-x-auto rounded-3xl border bg-popover p-2 text-popover-foreground shadow-lg">
          <TooltipButton
            size="icon-sm"
            variant="ghost"
            title={labels.bulkClearSelection}
            tooltip={labels.bulkClearSelection}
            onClick={() => table.resetRowSelection()}
          >
            <X />
          </TooltipButton>

          <Separator
            orientation="vertical"
            className="h-5 data-vertical:self-center"
          />

          <div
            className="flex shrink-0 items-center gap-2 whitespace-nowrap text-sm"
            id={descriptionId}
          >
            <Badge>{selectedCount}</Badge>
            <span className="hidden sm:inline">
              {labels.bulkSelectedRows(selectedCount)}
            </span>
          </div>

          {children != null && (
            <>
              <Separator
                orientation="vertical"
                className="h-5 data-vertical:self-center"
              />
              {children}
            </>
          )}
        </div>
      </div>
    </>
  );
}

import type { RowData } from "@tanstack/react-table";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "cn";
import {
  ArrowDownIcon,
  ArrowUpDownIcon,
  ArrowUpIcon,
  EyeOffIcon,
} from "lucide-react";
import type { ReactNode } from "react";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import type { Column } from "@/components/blocks/data-table/types";

export function DataTableColumnHeader<TData extends RowData, TValue>({
  column,
  title,
  sortable = true,
  align = "start",
  disableHiding = false,
  labels = defaultTableLabels,
  className,
}: {
  column: Column<TData, TValue>;
  title: ReactNode;
  sortable?: boolean;
  align?: "start" | "center" | "end";
  disableHiding?: boolean;
  labels?: TableLabels;
  className?: string;
}) {
  if (!sortable || !column.getCanSort())
    return (
      <div
        className={cn(
          "flex min-w-0 items-center",
          align === "center" && "justify-center",
          align === "end" && "justify-end",
          className,
        )}
      >
        {title}
      </div>
    );
  const sorted = column.getIsSorted();
  const SortIcon = sorted
    ? { asc: ArrowUpIcon, desc: ArrowDownIcon }[sorted]
    : ArrowUpDownIcon;

  return (
    <div
      className={cn(
        "flex min-w-0 items-center",
        align === "center" && "justify-center",
        align === "end" && "justify-end",
        className,
      )}
    >
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              variant="ghost"
              size="sm"
              className={cn(
                "relative min-w-0 border-0 px-2",
                align === "start" && "-ms-2",
                align === "end" && "-me-2 flex-row-reverse",
              )}
            />
          }
        >
          <span data-slot="data-table-header-label" className="truncate">
            {title}
          </span>
          <SortIcon
            className={cn(
              "size-3.5 shrink-0",
              align === "center" && "absolute -end-3.5",
            )}
          />
        </DropdownMenuTrigger>
        <DropdownMenuContent align={align}>
          <DropdownMenuGroup>
            <DropdownMenuItem onClick={() => column.toggleSorting(false)}>
              <ArrowUpIcon />
              {labels.sortAscending}
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => column.toggleSorting(true)}>
              <ArrowDownIcon />
              {labels.sortDescending}
            </DropdownMenuItem>
            <DropdownMenuItem
              disabled={!sorted}
              onClick={() => column.clearSorting()}
            >
              {labels.clearSorting}
            </DropdownMenuItem>
          </DropdownMenuGroup>
          {column.getCanHide() && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuItem
                  disabled={disableHiding}
                  onClick={() => column.toggleVisibility(false)}
                >
                  <EyeOffIcon />
                  {labels.hideColumn}
                </DropdownMenuItem>
              </DropdownMenuGroup>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

"use client";

import {
  closestCenter,
  DndContext,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { RowData } from "@tanstack/react-table";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";
import {
  GripVertical,
  PanelLeft,
  PanelRight,
  RotateCcw,
  SlidersHorizontal,
} from "lucide-react";
import { useId } from "react";
import { getColumnDropState, getSystemColumnPinning } from "@/components/blocks/data-table/columns";
import { CheckboxControl } from "@/components/blocks/data-table/filter-controls";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import { type ButtonSize, TooltipButton } from "@/components/blocks/data-table/tooltip-button";
import type { Column, ColumnPinningState, Table } from "@/components/blocks/data-table/types";

export interface DataTableColumnSettingsProps<TData extends RowData> {
  table: Table<TData>;
  defaultColumnOrder?: string[];
  defaultColumnPinning?: ColumnPinningState;
  size?: ButtonSize;
  disabled?: boolean;
  labels?: TableLabels;
  className?: string;
  align?: "start" | "center" | "end";
}

/** Column visibility, ordering, and pinning, independently placed by the caller. */
export function DataTableColumnSettings<TData extends RowData>({
  table,
  defaultColumnOrder = table
    .getAllFlatColumns()
    .filter((column) => column.columns.length === 0)
    .map((column) => column.id),
  defaultColumnPinning = getDefaultColumnPinning(table),
  size = "icon-sm",
  disabled = false,
  labels = defaultTableLabels,
  className,
  align = "end",
}: DataTableColumnSettingsProps<TData>) {
  return (
    <Popover>
      <PopoverTrigger
        render={
          <TooltipButton
            size={size}
            variant="ghost"
            tooltip={labels.columns}
            disabled={disabled}
            className={className}
          >
            <SlidersHorizontal />
          </TooltipButton>
        }
      />
      <PopoverContent
        align={align}
        sideOffset={4}
        className="w-64 max-w-[calc(100vw-2rem)] gap-2 p-2.5"
      >
        <TableColumnSettings
          labels={labels}
          table={table}
          defaultColumnOrder={defaultColumnOrder}
          defaultColumnPinning={defaultColumnPinning}
        />
      </PopoverContent>
    </Popover>
  );
}

function getDefaultColumnPinning<TData extends RowData>(
  table: Table<TData>,
): ColumnPinningState {
  const initial = table.initialState.columnPinning;
  if (initial?.start?.length || initial?.end?.length) return initial;
  const columns = table
    .getAllFlatColumns()
    .filter((column) => column.columns.length === 0);
  return {
    start: columns
      .filter(
        (column) =>
          (column.columnDef.meta?.pinned ??
            getSystemColumnPinning(column.id)) === "start",
      )
      .map((column) => column.id),
    end: columns
      .filter(
        (column) =>
          (column.columnDef.meta?.pinned ??
            getSystemColumnPinning(column.id)) === "end",
      )
      .map((column) => column.id),
  };
}

function TableColumnSettings<TData extends RowData>({
  table,
  defaultColumnOrder,
  defaultColumnPinning,
  labels,
}: Readonly<{
  table: Table<TData>;
  defaultColumnOrder: string[];
  defaultColumnPinning: ColumnPinningState;
  labels: TableLabels;
}>) {
  const dragContextId = useId();
  const columns = table
    .getAllLeafColumns()
    .filter((column) => !column.columnDef.meta?.filterOnly);
  const tableState = table.store.state;
  const columnOrder = tableState.columnOrder.length
    ? tableState.columnOrder
    : defaultColumnOrder;
  const columnLookup = new Map(
    columns.map((column) => [column.id, column] as const),
  );
  const leftPinnedIds = new Set(tableState.columnPinning.start ?? []);
  const rightPinnedIds = new Set(tableState.columnPinning.end ?? []);
  const visualColumnOrder = [
    ...(tableState.columnPinning.start ?? []),
    ...columnOrder.filter(
      (columnId) =>
        !leftPinnedIds.has(columnId) && !rightPinnedIds.has(columnId),
    ),
    ...(tableState.columnPinning.end ?? []),
  ];
  const orderedIds = new Set<string>();
  const orderedColumns = [
    ...visualColumnOrder.flatMap((columnId) => {
      const column = columnLookup.get(columnId);
      if (!column || orderedIds.has(column.id)) return [];
      orderedIds.add(column.id);
      return [column];
    }),
    ...columns.filter((column) => {
      if (orderedIds.has(column.id)) return false;
      orderedIds.add(column.id);
      return true;
    }),
  ];
  const hideableColumns = orderedColumns.filter(
    (column) =>
      column.getCanHide() && getSystemColumnPinning(column.id) === undefined,
  );
  const canPinColumns = table.options.enableColumnPinning !== false;
  const visibleDataColumnCount = table
    .getVisibleLeafColumns()
    .filter((column) => getSystemColumnPinning(column.id) === undefined).length;
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  return (
    <>
      <div className="flex items-center justify-between gap-2 px-1">
        <span className="font-medium text-foreground text-sm">
          {labels.columns}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="xs"
          onClick={() => {
            table.resetColumnVisibility();
            table.setColumnOrder(defaultColumnOrder);
            if (canPinColumns) table.setColumnPinning(defaultColumnPinning);
          }}
        >
          <RotateCcw data-icon="inline-start" />
          {labels.reset}
        </Button>
      </div>
      <Separator />
      <DndContext
        id={dragContextId}
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={({ active, over }) => {
          if (!over || active.id === over.id) return;

          const activeId = String(active.id);
          const overId = String(over.id);
          const sortableOrder = hideableColumns.map((column) => column.id);
          const targetSide = columnLookup.get(overId)?.getIsPinned() ?? false;
          const next = getColumnDropState({
            columnOrder,
            sortableOrder,
            columnPinning: tableState.columnPinning,
            activeId,
            overId,
            targetSide,
            pinningEnabled: canPinColumns,
          });
          if (!next) return;

          table.setColumnOrder(next.order);
          if (canPinColumns) table.setColumnPinning(next.pinning);
        }}
      >
        <SortableContext
          items={hideableColumns.map((column) => column.id)}
          strategy={verticalListSortingStrategy}
        >
          <div className="grid max-h-72 gap-1 overflow-y-auto overscroll-contain">
            {hideableColumns.map((column) => (
              <SortableColumnItem
                key={column.id}
                column={column}
                canPin={canPinColumns}
                lastVisible={
                  column.getIsVisible() && visibleDataColumnCount <= 1
                }
                labels={labels}
              />
            ))}
          </div>
        </SortableContext>
      </DndContext>
    </>
  );
}

function SortableColumnItem<TData extends RowData>({
  column,
  canPin,
  lastVisible,
  labels,
}: Readonly<{
  column: Column<TData, unknown>;
  canPin: boolean;
  lastVisible: boolean;
  labels: TableLabels;
}>) {
  const checkboxId = useId();
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: column.id,
  });
  const pinned = column.getIsPinned();
  const canPinColumn = canPin && column.getCanPin();
  const leftPinned = pinned === "start";
  const rightPinned = pinned === "end";

  return (
    <div
      ref={setNodeRef}
      style={{
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
      }}
      className="grid min-h-9 grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-1 rounded-xl px-1 py-1 text-sm hover:bg-muted/60"
    >
      <Button
        variant="ghost"
        size="icon-xs"
        {...attributes}
        {...listeners}
        className="cursor-grab touch-none text-muted-foreground active:cursor-grabbing"
        aria-label={labels.dragReorder}
      >
        <GripVertical />
      </Button>
      <Label
        htmlFor={checkboxId}
        className="flex min-w-0 flex-1 cursor-pointer select-none items-center gap-2"
      >
        <CheckboxControl
          id={checkboxId}
          checked={column.getIsVisible()}
          disabled={!column.getCanHide() || lastVisible}
          onCheckedChange={(checked) =>
            column.toggleVisibility(checked === true)
          }
          onClick={(event) => event.stopPropagation()}
        />
        <span className="truncate">
          {typeof column.columnDef.header === "string"
            ? column.columnDef.header
            : column.id}
        </span>
      </Label>
      {canPinColumn && (
        <div className="flex shrink-0 items-center gap-0.5">
          <Button
            variant="ghost"
            size="icon-xs"
            className="shrink-0 text-muted-foreground aria-pressed:bg-primary/10 aria-pressed:text-primary aria-pressed:hover:bg-primary/15 aria-pressed:hover:text-primary"
            aria-pressed={leftPinned}
            aria-label={leftPinned ? labels.unpinStart : labels.pinStart}
            title={leftPinned ? labels.unpinStart : labels.pinStart}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              column.pin(leftPinned ? false : "start");
            }}
          >
            <PanelLeft className="rtl:-scale-x-100" />
          </Button>
          <Button
            variant="ghost"
            size="icon-xs"
            className="shrink-0 text-muted-foreground aria-pressed:bg-primary/10 aria-pressed:text-primary aria-pressed:hover:bg-primary/15 aria-pressed:hover:text-primary"
            aria-pressed={rightPinned}
            aria-label={rightPinned ? labels.unpinEnd : labels.pinEnd}
            title={rightPinned ? labels.unpinEnd : labels.pinEnd}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              column.pin(rightPinned ? false : "end");
            }}
          >
            <PanelRight className="rtl:-scale-x-100" />
          </Button>
        </div>
      )}
    </div>
  );
}

import type { ColumnPinningState } from "@/components/blocks/data-table/types";

export const CONTROL_COLUMN_WIDTH = 40;

/** Default pinning for built-in utility columns. */
export function getSystemColumnPinning(id: string | undefined) {
  if (id === "select" || id === "drag") return "start";
  if (id === "actions" || id === "operation") return "end";
  return undefined;
}

/** Calculates column order and pinning after a settings-panel drop. */
export function getColumnDropState({
  columnOrder,
  sortableOrder,
  columnPinning,
  activeId,
  overId,
  targetSide,
  pinningEnabled,
}: {
  columnOrder: string[];
  sortableOrder: string[];
  columnPinning: ColumnPinningState;
  activeId: string;
  overId: string;
  targetSide: false | "start" | "end";
  pinningEnabled: boolean;
}) {
  const oldIndex = sortableOrder.indexOf(activeId);
  const newIndex = sortableOrder.indexOf(overId);
  if (oldIndex === -1 || newIndex === -1 || oldIndex === newIndex)
    return undefined;

  const nextSortableOrder = moveItem(sortableOrder, oldIndex, newIndex);
  const sortableIds = new Set(nextSortableOrder);
  const iterator = nextSortableOrder[Symbol.iterator]();
  const order = columnOrder.map((columnId) =>
    sortableIds.has(columnId) ? (iterator.next().value ?? columnId) : columnId,
  );

  if (!pinningEnabled) return { order, pinning: columnPinning };

  const leftIds = new Set(columnPinning.start ?? []);
  const rightIds = new Set(columnPinning.end ?? []);
  leftIds.delete(activeId);
  rightIds.delete(activeId);
  if (targetSide === "start") leftIds.add(activeId);
  if (targetSide === "end") rightIds.add(activeId);

  return {
    order,
    pinning: {
      start: [
        ...(columnPinning.start ?? []).filter(
          (columnId) => !sortableIds.has(columnId),
        ),
        ...nextSortableOrder.filter((columnId) => leftIds.has(columnId)),
      ],
      end: [
        ...nextSortableOrder.filter((columnId) => rightIds.has(columnId)),
        ...(columnPinning.end ?? []).filter(
          (columnId) => !sortableIds.has(columnId),
        ),
      ],
    },
  };
}

function moveItem<T>(items: T[], from: number, to: number) {
  const next = [...items];
  const [item] = next.splice(from, 1);
  if (item !== undefined) next.splice(to, 0, item);
  return next;
}

