export function TooltipButton({
  tooltip,
  ...props
}: ComponentProps<typeof Button> & { tooltip: ReactNode }) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            {...props}
            aria-label={
              props["aria-label"] ??
              (typeof tooltip === "string" ? tooltip : undefined)
